{
  "name": "Admin Access Policy",
  "description": "Grants admin access during business hours",
  "rules": {
    "effect": "allow",
    "actions": ["read:*", "write:*"],
    "conditions": {
      "timeRange": { "start": "09:00", "end": "17:00", "timezone": "America/New_York" },
      "ipRange": ["192.168.1.0/24"]
    }
  }
}

{
  "to": ["user@example.com"],
  "cc": ["admin@example.com"],
  "subject": "Test Email",
  "html": "<h1>Hello</h1><p>This is a test email.</p>",
  "text": "Hello, this is a test email.",
  "from": "noreply@example.com",
  "templateId": "template-uuid",
  "variables": { "name": "John" }
}

{
  "name": "High Security Access",
  "description": "Requires MFA and device verification",
  "rules": {
    "requireMfa": true,
    "requireDeviceVerified": true,
    "maxAgeSeconds": 3600
  },
  "priority": 100
}
